const cutoff = Date.now() - 60 * 60 * 1000; // last hour
const fresh = $input.all()
  .map(i => i.json)
  .filter(item => new Date(item.isoDate || item.pubDate).getTime() > cutoff);
return fresh.map(item => ({ json: {
  title: item.title,
  link: item.link,
  snippet: (item.contentSnippet || '').slice(0, 180)
} }));
